-- Business tables for the ticket system (wi-t1000076).
-- All timestamps are INTEGER milliseconds (Date.now()).
-- All IDs are TEXT UUID v4 strings generated by the application layer.

CREATE TABLE companies (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE TABLE departments (
  id TEXT PRIMARY KEY,
  company_id TEXT NOT NULL REFERENCES companies(id),
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE INDEX departments_company_idx ON departments(company_id);

CREATE TABLE user_profiles (
  user_id TEXT PRIMARY KEY REFERENCES users(id),
  company_id TEXT REFERENCES companies(id),
  department_id TEXT REFERENCES departments(id),
  full_name TEXT
);

CREATE INDEX user_profiles_company_idx ON user_profiles(company_id);

CREATE TABLE business_groups (
  id TEXT PRIMARY KEY,
  company_id TEXT NOT NULL REFERENCES companies(id),
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE INDEX business_groups_company_idx ON business_groups(company_id);

CREATE TABLE tickets (
  id TEXT PRIMARY KEY,
  company_id TEXT NOT NULL REFERENCES companies(id),
  subject TEXT NOT NULL,
  description TEXT NOT NULL,
  category TEXT NOT NULL,
  sla_priority TEXT NOT NULL,
  status TEXT NOT NULL,
  submitter_user_id TEXT NOT NULL REFERENCES users(id),
  assigned_group_id TEXT REFERENCES business_groups(id),
  assigned_user_id TEXT REFERENCES users(id),
  handler_user_id TEXT REFERENCES users(id),
  created_at INTEGER NOT NULL,
  processed_at INTEGER
);

CREATE INDEX tickets_company_idx ON tickets(company_id);
CREATE INDEX tickets_status_idx ON tickets(company_id, status);
CREATE INDEX tickets_submitter_idx ON tickets(submitter_user_id);

CREATE TABLE ticket_replies (
  id TEXT PRIMARY KEY,
  ticket_id TEXT NOT NULL REFERENCES tickets(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  content TEXT NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE INDEX ticket_replies_ticket_idx ON ticket_replies(ticket_id, created_at);

CREATE TABLE business_group_members (
  id TEXT PRIMARY KEY,
  group_id TEXT NOT NULL REFERENCES business_groups(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  created_at INTEGER NOT NULL
);

CREATE INDEX business_group_members_group_idx ON business_group_members(group_id);
CREATE INDEX business_group_members_user_idx ON business_group_members(user_id);
CREATE UNIQUE INDEX business_group_members_unique ON business_group_members(group_id, user_id);

CREATE TABLE category_assignment_rules (
  id TEXT PRIMARY KEY,
  company_id TEXT NOT NULL REFERENCES companies(id),
  category TEXT NOT NULL,
  group_id TEXT NOT NULL REFERENCES business_groups(id),
  created_at INTEGER NOT NULL
);

CREATE UNIQUE INDEX category_assignment_rules_unique ON category_assignment_rules(company_id, category);

CREATE TABLE ticket_evaluations (
  id TEXT PRIMARY KEY,
  ticket_id TEXT NOT NULL REFERENCES tickets(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  rating INTEGER NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE INDEX ticket_evaluations_ticket_idx ON ticket_evaluations(ticket_id);
CREATE UNIQUE INDEX ticket_evaluations_unique ON ticket_evaluations(ticket_id, user_id);
